class Driver {
  + driverID : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licensePlate : string
  + isInRepairShop : boolean
}

class Route {
  + routeNumber : int
}

class Shift {
  + shiftType : ShiftType
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class Assignment {
  + date : date
}

class BusRouteAssignment {
  + date : date
}

